contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _value, bool asOwner) public payable {
        // Fund c so that both success and revert cases are reachable.
        require(address(this).balance >= 1);
        (bool ok, ) = address(c).call{value: 1}("");
        // Precondition: only owner calls are interesting for the success path.
        if (!asOwner && msg.sender != address(this)) {
            // cannot change msg.sender; nothing to set up
        }

        bool reverted;
        uint balanceBefore = address(c).balance;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;

        bool owner = (msg.sender == c.owner());
        bool enough = balanceBefore >= _value;

        // General rule: withdraw reverts iff caller is not owner or value exceeds balance;
        // on success, c's balance decreases by exactly _value.
        assert(reverted == (!owner || !enough));
        assert(reverted || balanceAfter + _value == balanceBefore);
    }

    receive() external payable {}
}

