contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    function run(address _target, uint _value, bytes memory _data) public payable {
        uint before = address(c).balance;
        bool reverted;
        try c.sendMoney(_target, _value, _data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (before < _value) {
            assert(reverted);
            assert(address(c).balance == before);
        } else {
            bool probeSuccess;
            try this.solProbe(_target, _data) {
                probeSuccess = true;
            } catch {
                probeSuccess = false;
            }
            if (probeSuccess) {
                assert(!reverted);
                assert(address(c).balance == before - _value);
                (bool ok, bytes memory ret) = _target.call{value: _value}(_data);
                assert(ok);
                assert(keccak256(ret) == keccak256(_data));
            } else {
                assert(reverted);
                assert(address(c).balance == before);
            }
        }
    }

    function solProbe(address _target, bytes memory _data) public payable {
        (bool ok, bytes memory ret) = _target.call{value: 0}(_data);
        require(ok);
        require(keccak256(ret) == keccak256(_data));
    }

    receive() external payable {}

    fallback() external payable {
        revert();
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _target, uint _value, bytes memory _data) public payable {
        require(address(this).balance >= _value, "not enough test balance");
        uint before = address(c).balance;

        bool reverted;
        try c.sendMoney(_target, _value, _data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool targetAlive;
        try this.echoCall(_target, _data) {
            targetAlive = true;
        } catch {
            targetAlive = false;
        }

        if (before < _value || !targetAlive) {
            assert(reverted);
            assert(address(c).balance == before);
        } else {
            assert(!reverted);
            assert(address(c).balance == before - _value);
        }
    }

    function echoCall(address _target, bytes memory _data) public payable {
        (bool ok, bytes memory ret) = _target.call{value: 0}(_data);
        require(ok);
        require(keccak256(ret) == keccak256(_data));
    }

    receive() external payable {}

    fallback() external payable {
        revert();
    }
}

