    constructor(C _c) { c = _c; }

    function run(address _target, uint _value, bytes memory _data) public payable {
        require(address(this).balance >= _value, "not enough test balance");

        uint before = address(c).balance;

        bool reverted;
        try c.sendMoney(_target, _value, _data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || (!reverted && address(c).balance == before - _value));
    }

    receive() external payable {}
}

