contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _value) public payable {
        require(address(this).balance >= _value, "insufficient test balance");

        // Fund C so that owner withdrawals can succeed when _value <= address(c).balance.
        c.fallback{value: _value}();

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();

        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount();

        assert(
            reverted ||
            (
